const auth = $input.first().json.headers?.authorization || '';
if (!auth.startsWith('Bearer ')) return [{ json: { _error: 'AUTH_MISSING_TOKEN', _status: 401 } }];
const token = auth.slice(7);
try {
  const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64url').toString('utf8'));
  if (!payload.sub) throw new Error('No sub');
  if (payload.exp && Date.now()/1000 > payload.exp) throw new Error('JWT expired');
  if (!payload.tenant_id) throw new Error('No tenant_id');
  const body = $input.first().json.body || {};
  const projectId = (body.project_id || '').trim();
  if (!projectId) return [{ json: { _error: 'VALIDATION_FAILED', _status: 400, _details: 'project_id requerido' } }];
  return [{ json: {
    user_id: payload.sub,
    tenant_id: payload.tenant_id,
    role: payload.role || 'architect',
    project_id: projectId,
    request_id: 'req_' + Math.random().toString(36).slice(2, 10)
  }}];
} catch (e) {
  return [{ json: { _error: 'AUTH_INVALID_TOKEN', _status: 401, _details: e.message } }];
}

const project = $input.first()?.json;
const sess = $('Decode JWT + Body').first().json;
if (!project || !project.id) {
  return [{ json: { _error: 'PROJECT_NOT_FOUND', _status: 404, _details: 'project_id no existe o sin acceso por RLS' } }];
}
return [{ json: {
  ...sess,
  project: {
    id: project.id,
    name: project.name,
    project_type: project.project_type,
    location_province: project.location_province,
    location_city: project.location_city,
    property_type: project.property_type,
    property_area_m2: project.property_area_m2 ? parseFloat(project.property_area_m2) : null,
    budget_target: project.budget_target ? parseFloat(project.budget_target) : null,
    urgency: project.urgency,
    current_phase: project.current_phase
  }
}}];

const ctx = $('Validate Project').first().json;
const project = ctx.project;
const briefingRows = $('Load Briefing').all().map(i => i.json).filter(b => b && b.id);
const designRows = $('Load Design Option').all().map(i => i.json).filter(d => d && d.id);
const materialRows = $('Load Materials').all().map(i => i.json).filter(m => m && m.id);
const priceRows = $('Load Price References').all().map(i => i.json).filter(p => p && p.category);
const directiveRows = $input.all().map(i => i.json).filter(d => d && d.directiva);

if (briefingRows.length === 0) {
  return [{ json: { _error: 'BRIEFING_NOT_APPROVED', _status: 422, _details: 'No hay briefing aprobado para este proyecto. agent_costs requiere briefing en estado approved.', request_id: ctx.request_id }}];
}
if (designRows.length === 0) {
  return [{ json: { _error: 'DESIGN_NOT_SELECTED', _status: 422, _details: 'No hay design_option seleccionada. El cliente debe elegir una opcion antes de calcular costes.', request_id: ctx.request_id }}];
}

const briefing = briefingRows[0];
const design = designRows[0];

// Resumen materials: total por categoria + total absoluto
const materialsByCategory = {};
let materialsTotal = 0;
for (const m of materialRows) {
  const cat = m.category || 'otro';
  const total = m.total_estimated ? parseFloat(m.total_estimated) : 0;
  if (!materialsByCategory[cat]) materialsByCategory[cat] = { count: 0, total: 0, items: [] };
  materialsByCategory[cat].count += 1;
  materialsByCategory[cat].total += total;
  materialsByCategory[cat].items.push({
    name: m.name,
    unit_price: m.unit_price ? parseFloat(m.unit_price) : null,
    unit: m.unit,
    qty: m.quantity_estimated ? parseFloat(m.quantity_estimated) : null,
    total: total,
    quality_tier: m.quality_tier
  });
  materialsTotal += total;
}

// Resumen prices: por categoria
const pricesByCategory = {};
for (const p of priceRows) {
  const cat = p.category;
  if (!pricesByCategory[cat]) pricesByCategory[cat] = [];
  pricesByCategory[cat].push({
    partida: p.partida,
    unit: p.unit,
    min: p.min_price ? parseFloat(p.min_price) : null,
    avg: p.avg_price ? parseFloat(p.avg_price) : null,
    max: p.max_price ? parseFloat(p.max_price) : null
  });
}

const directivesText = directiveRows.length
  ? directiveRows.map(d => `- (${d.prioridad}) ${d.directiva}${d.contexto ? ' [' + d.contexto + ']' : ''}`).join('\n')
  : '(sin directivas activas en categoria presupuesto)';

const systemPrompt = `Eres agent_costs, especialista en presupuestos de reforma residencial en Espana.\n\nREGLAS DE ORO:\n- Usa price_references CYPE como BASELINE objetivo. Si los material_items del proyecto se desvian > 20% por categoria, MARCALO en risk_notes.\n- Aplica IVA 10% obras de reforma residencial (no 21%) salvo que la obra incluya cambio de uso.\n- Incluye 8-12% de imprevistos sobre el subtotal de obra (NO sobre materiales premium).\n- Genera 3 scenarios: economico (-15%), recomendado, premium (+25%).\n- Compara contra budget_target del proyecto y calcula deviation_status: within_budget (<=5%), slight_over (5-15%), over_budget (15-30%), critical_over (>30%).\n- El arquitecto firma. Tu propones. Sin tecnicismos legales.\n- DEVUELVE SOLO JSON valido, sin texto fuera del JSON.`;

const userPrompt = `CONTEXTO DEL PROYECTO:\n- Nombre: ${project.name}\n- Tipo: ${project.project_type}\n- Superficie: ${project.property_area_m2 ?? '?'} m2\n- Ubicacion: ${project.location_city ?? '?'}, ${project.location_province ?? '?'}\n- Budget target: ${project.budget_target ?? 'no especificado'} EUR\n\nBRIEFING APROBADO:\n- Summary: ${briefing.summary?.slice(0, 600) ?? ''}\n- Rooms afectadas: ${JSON.stringify(briefing.rooms_affected ?? [])}\n- Constraints: ${JSON.stringify(briefing.constraints ?? [])}\n\nDESIGN OPTION SELECCIONADA:\n- Titulo: ${design.title}\n- Logica intervencion: ${(design.intervention_logic || '').slice(0, 800)}\n- Rooms layout: ${JSON.stringify(design.rooms_layout ?? [])}\n- Cons declarados: ${JSON.stringify(design.cons ?? [])}\n\nMATERIALES YA SELECCIONADOS (${materialRows.length} items, total ${materialsTotal.toFixed(2)} EUR):\n${JSON.stringify(materialsByCategory, null, 2)}\n\nREFERENCIAS CYPE (baselines de mercado por categoria):\n${JSON.stringify(pricesByCategory, null, 2)}\n\nDIRECTIVAS DEL ESTUDIO (categoria presupuesto):\n${directivesText}\n\nTAREA:\n1. Genera un BREAKDOWN por partidas (8-15 partidas tipicas: demolicion, albanileria, fontaneria, electricidad, climatizacion, carpinteria, pavimentos, revestimientos, sanitarios, pintura, cocina, otros). Cada partida con: name, category, base_cost, materials_cost, labor_cost, total, notes.\n2. Calcula total_estimated = subtotal_obra + imprevistos (8-12%) + IVA 10%.\n3. Compara con budget_target del proyecto, calcula deviation_pct y deviation_status.\n4. Genera 3 SCENARIOS (economico/recomendado/premium) con su total y diferencias clave.\n5. Lista 3-6 ADJUSTMENTS_SUGGESTED para reducir coste si over_budget.\n6. Lista ASSUMPTIONS criticas (precios validos a fecha, sin imprevistos estructurales no detectados, etc.).\n7. RISK_NOTES: cualquier desviacion >20% vs CYPE, materiales premium dudosos, plazos cortos que encarezcan.\n\nOUTPUT (JSON estricto, SOLO el JSON):\n{\n  \"version\": 1,\n  \"total_estimated\": 45000,\n  \"budget_target\": ${project.budget_target ?? null},\n  \"deviation_pct\": 12.5,\n  \"deviation_status\": \"slight_over\",\n  \"breakdown\": [\n    { \"name\": \"Demolicion\", \"category\": \"obra_basica\", \"base_cost\": 2500, \"materials_cost\": 200, \"labor_cost\": 2300, \"total\": 2500, \"notes\": \"...\" }\n  ],\n  \"adjustments_suggested\": [ { \"item\": \"...\", \"saving_eur\": 1500, \"impact\": \"...\" } ],\n  \"scenarios\": {\n    \"economico\": { \"total\": 38000, \"key_changes\": [\"...\"] },\n    \"recomendado\": { \"total\": 45000, \"key_changes\": [] },\n    \"premium\": { \"total\": 55000, \"key_changes\": [\"...\"] }\n  },\n  \"assumptions\": [\"...\"],\n  \"risk_notes\": \"...\"\n}`;

return [{ json: {
  user_id: ctx.user_id,
  tenant_id: ctx.tenant_id,
  project_id: project.id,
  request_id: ctx.request_id,
  budget_target: project.budget_target,
  materials_total: materialsTotal,
  materials_count: materialRows.length,
  llm_payload: {
    model: 'gpt-4o',
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userPrompt }
    ],
    temperature: 0.2,
    max_tokens: 2500,
    response_format: { type: 'json_object' }
  }
}}];

