const llm = $input.first()?.json;
const built = $('Build Prompt').first().json;
const raw = llm?.choices?.[0]?.message?.content || '{}';
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  return [{ json: { _error: 'LLM_INVALID_JSON', _status: 502, _details: e.message, _raw: raw.slice(0, 500), request_id: built.request_id } }];
}
const usage = llm?.usage || {};
const breakdown = Array.isArray(parsed.breakdown) ? parsed.breakdown : [];
const scenarios = parsed.scenarios || {};

return [{ json: {
  user_id: built.user_id,
  tenant_id: built.tenant_id,
  project_id: built.project_id,
  request_id: built.request_id,
  total_estimated: parsed.total_estimated ?? 0,
  budget_target: built.budget_target,
  deviation_pct: parsed.deviation_pct ?? null,
  deviation_status: parsed.deviation_status ?? null,
  breakdown_count: breakdown.length,
  output: {
    version: parsed.version || 1,
    breakdown,
    adjustments_suggested: parsed.adjustments_suggested || [],
    scenarios,
    assumptions: parsed.assumptions || [],
    risk_notes: parsed.risk_notes || null
  },
  model: llm?.model || 'gpt-4o',
  tokens_in: usage.prompt_tokens || 0,
  tokens_out: usage.completion_tokens || 0
}}];

